"use strict";
/* =========================================================================
   СтройИД — прототип интерфейса v2 (по ТЗ v12.0 и уточнениям)
   Объект → Системы (схемы при необходимости) → АОСР (сколько угодно)
   Один файл, работает локально. Данные — в localStorage браузера.
   ========================================================================= */
const iso = (minAgo = 0) => new Date(Date.now() - minAgo * 60e3).toISOString();
const hm = (s) =>
  new Date(s).toLocaleTimeString("ru-RU", {
    hour: "2-digit",
    minute: "2-digit",
  });
const $ = (s) => document.querySelector(s);
const uid = () => Math.random().toString(36).slice(2, 9);
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
const pad = (n) => String(n).padStart(3, "0");
const today = () => {
  const d = new Date();
  return (
    d.getFullYear() +
    "-" +
    String(d.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(d.getDate()).padStart(2, "0")
  );
};
const fmtD = (d) => (d ? String(d).split("-").reverse().join(".") : "—");
const nowStr = () =>
  new Date().toLocaleString("ru-RU", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
const addDays = (s, k) => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + k);
  return d.toISOString().slice(0, 10);
};
const clone = (o) => JSON.parse(JSON.stringify(o));
const cap1 = (s) => String(s).charAt(0).toLowerCase() + String(s).slice(1);

