  return `<details class="card"${open ? " open" : ""}><summary>Замечания ${open ? `<span class="pill p-a">${open}</span>` : ""}<span class="r">${B("+ Добавить", "remAdd", `data-ent="${ent}" data-id="${id}"`, "sm ghost")}</span></summary>
 ${list.length ? `<div class="tw"><table class="tbl"><tbody>${list.map((r) => `<tr><td style="width:150px"><input type="date" value="${r.date}" data-ent="${ent}" data-id="${id}" data-f="remarks.#${r.id}.date"></td><td><input value="${esc(r.text)}" placeholder="Текст замечания" data-ent="${ent}" data-id="${id}" data-f="remarks.#${r.id}.text"></td><td style="width:120px"><label class="ck small"><input type="checkbox" ${r.done ? "checked" : ""} data-ent="${ent}" data-id="${id}" data-f="remarks.#${r.id}.done" data-rr="1">Устранено</label></td><td style="width:40px">${B(ic("trash"), "remRm", `data-ent="${ent}" data-id="${id}" data-r="${r.id}" title="Удалить"`, "sm icon ghost")}</td></tr>`).join("")}</tbody></table></div>` : '<div class="mut small">Замечаний нет</div>'}</details>`;
