A.wordPreview = async (d) => {
  try {
    const { p, profile } = wordUIContext(),
      t = tpl(d.id);
    if (!p || !t?.fileKey) throw Error("Выберите объект и загрузите DOCX");
    const vols = volumeList(p),
      base =
        vols.find((v) => v.s && (!profile || v.sp.profileId === profile.id)) ||
        vols[0];
    let id = wordKey(t) === "reg" ? "reg" : "title";
    const key = wordKey(t),
      items = blocksFor(p, base).find((b) => b.key === key)?.items || [];
    if (key === "photos") {
      const a = base.s?.acts.find((a) => a.photos.length);
      if (a) id = "p" + a.id;
    } else if (items.length) id = items[0].id;
    // Object-wide sections may live in Tom 1 even when the default preview volume is a system.
    const vol =
      items.length || ["title", "reg", "photos"].includes(key)
        ? base
        : vols.find((v) =>
            blocksFor(p, v).some((b) => b.key === key && b.items.length),
          ) || base;
    if (!["title", "reg", "photos"].includes(key))
      id = blocksFor(p, vol).find((b) => b.key === key)?.items[0]?.id || id;
    const context = validateDocumentContext(
      wordContext(p, vol, id),
      t.tags || [],
    );
    if (key === "reg") {
      context.collections.Реестр = registry(p, vol)
        .rows.filter((r) => !r.book && (!t.tags?.includes("Реестр.ИтогоСтраниц") || r.id !== "title"))
        .map((r) => ({
          Номер: r.n,
          Тип: r.type,
          Наименование: r.name,
          Номер_Дата: r.nd,
          КоличествоСтраниц: r.to - r.from + 1,
          Листы: r.from === r.to ? String(r.from) : r.from + "-" + r.to,
        }));
      if (t.tags?.includes("Реестр.ИтогоСтраниц")) {
        context.collections.Реестр.sort((a, b) => Number(b.Тип === "Реестр") - Number(a.Тип === "Реестр"));
        context.collections.Реестр.forEach((r, i) => {
          r.Номер = i + 1;
          if (i === 0 && r.Тип === "Реестр" && !r.Номер_Дата)
            r.Номер_Дата = "Реестр исполнительной документации";
        });
        context.values["Реестр.ИтогоСтраниц"] = context.collections.Реестр.reduce((sum, r) => sum + r.КоличествоСтраниц, 0);
      }
      context.values["Реестр.Текст"] = context.values["Документ.Содержание"] =
        context.collections.Реестр
          .map((r) => r.Номер + ". " + r.Наименование + " — " + r.Листы)
          .join("\n");
    }
    await desktopTrack(
      nativeCall("openFilledWord", { key: t.fileKey, ...context }),
    );
  } catch (e) {
    modal("Шаблон не заполнен", "<p>" + esc(e.message) + "</p>", [
      { l: "Закрыть" },
    ]);
  }
};
