const wordPreviousSources = pdfSources;
pdfSources = (p, vol) => {
  const sources = wordPreviousSources(p, vol);
  for (const block of blocksFor(p, vol))
    for (const item of block.items) {
      const source = sources.get(item.id),
        key = item.id.startsWith("q")
          ? block.key === "pass"
            ? "pass"
            : "quality"
          : item.id.startsWith("p") && item.type === "Фототаблица"
            ? "photos"
            : item.type === "АООК"
              ? "aook"
              : item.type.startsWith("АОСР")
                ? "aosr"
                : block.key;
      const t = wordChoice(p, vol, key);
      if (!t) continue;
      // Real uploaded PDFs (including signed scans) always remain originals in the assembled file.
      if (
        (source?.kind === "pdf" && (source.key || source.declaredFile)) ||
        (source?.kind === "missing" &&
          item.id.startsWith("a") &&
          source.error?.includes("связи"))
      )
        continue;
      if (!t.fileKey) {
        sources.set(item.id, {
          kind: "missing",
          error: "загрузите файл выбранного Word-шаблона «" + t.name + "»",
        });
        continue;
      }
      let context;
      try {
        context = validateDocumentContext(
          wordContext(p, vol, item.id),
          t.tags || [],
        );
      } catch (e) {
        sources.set(item.id, { kind: "missing", error: e.message });
        continue;
      }
      sources.set(item.id, {
        kind: item.id === "reg" ? "registry" : "word",
        templateKey: t.fileKey,
        templateName: t.name,
        ...context,
      });
    }
  return sources;
};
