let folderFileIndex = null,
  folderFileState = null,
  folderFileVersion = -1,
  folderFileSavedState = null;
function folderFileMatches(text) {
  let found = folderFileIndex.get(text);
  if (found) return found;
  for (
    let end = text.lastIndexOf(" · ");
    end > 0;
    end = text.lastIndexOf(" · ", end - 1)
  ) {
    found = folderFileIndex.get(text.slice(0, end));
    if (found) return found;
  }
  return [];
}
const folderRender = render;
render = () => {
  folderRender();
  document
    .querySelectorAll(
      '#content [data-h="#/import"],#content a[href="#/import"],#content [data-a="exportJson"],#content [data-a="importJson"],#content [data-a="resetDemo"]',
    )
    .forEach((e) => e.remove());
  if (
    !folderFileIndex ||
    folderFileState !== S ||
    folderFileVersion !== desktopEditVersion ||
    folderFileSavedState !== desktopSavedState
  ) {
    const all = [];
    function walk(x) {
      if (!x || typeof x !== "object") return;
      if (x.file) all.push(x);
      Object.values(x).forEach((v) => {
        if (v && typeof v === "object")
          Array.isArray(v) ? v.forEach(walk) : walk(v);
      });
    }
    walk(S.projects);
    walk(S.lib);
    folderFileIndex = new Map();
    for (const record of all) {
      const records = folderFileIndex.get(record.file) || [];
      records.push(record);
      folderFileIndex.set(record.file, records);
    }
    folderFileState = S;
    folderFileVersion = desktopEditVersion;
    folderFileSavedState = desktopSavedState;
  }
  document
    .querySelectorAll("#content .file .nm,#content span.small,#content td.t2")
    .forEach((el) => {
      if (el.children.length) return;
      const text = el.textContent.trim(),
        matches = folderFileMatches(text);
      if (!matches.length) return;
      const keys = [...new Set(matches.map((x) => x.fileKey).filter(Boolean))];
      if (keys.length === 1)
        el.innerHTML = B(
          text,
          "openBlob",
          `data-key="${esc(keys[0])}"`,
          "sm ghost",
        );
      else if (!keys.length)
        el.innerHTML =
          '<span class="pill p-r">Файл не загружен: ' + esc(text) + "</span>";
    });
  const r = route(),
    o =
      r[0] === "p"
        ? proj(r[1])
        : r[0] === "s"
          ? getEnt("sys", r[1])
          : r[0] === "a"
            ? getEnt("act", r[1])
            : r[0] === "m"
              ? getEnt("mat", r[1])
              : r[0] === "j"
                ? getEnt("jr", r[1])
                : null;
  if (r[0] !== "p" && o?.attachments?.length)
    $("#content .page")?.insertAdjacentHTML(
      "beforeend",
      `<div class="card"><h3>Дополнительные документы</h3>${o.attachments.map((f) => `<div class="row mb"><span class="grow">${esc(f.name || f.file)}</span>${B("Открыть", "openBlob", `data-key="${esc(f.fileKey)}"`)}</div>`).join("")}</div>`,
    );
};
