document.addEventListener(
  "keydown",
  (event) => {
    const root = event.target.closest?.("[data-org-role]");
    if (!root) return;
    const list = root.querySelector(".org-role-list"),
      options = [...list.querySelectorAll('[role="option"]')];
    if (event.key === "Escape" && !list.hidden) {
      event.preventDefault();
      event.stopImmediatePropagation();
      closeOrganizationRole(root, true);
      return;
    }
    if (event.key === "Tab" && !list.hidden) {
      closeOrganizationRole(root, true);
      return;
    }
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    if (list.hidden) {
      A.orgRoleOpen(
        root.querySelector(".org-role-trigger").dataset,
        root.querySelector(".org-role-trigger"),
      );
      return;
    }
    const index = options.indexOf(document.activeElement),
      next =
        event.key === "Home"
          ? 0
          : event.key === "End"
            ? options.length - 1
            : (index + (event.key === "ArrowDown" ? 1 : -1) + options.length) %
              options.length;
    options[next].focus();
  },
  true,
);
