document.addEventListener("change", (event) => {
  const el = event.target,
    k = el.dataset.assembly;
  if (!k) return;
  const p = proj(el.dataset.p),
    c = assemblyPick(p);
  if (k === "scenario") {
    c.scenario = el.value;
    if (["1", "4", "5", "9"].includes(c.scenario))
      c.executions = c.executions.slice(0, 1);
  } else if (k === "execution") {
    if (["1", "4", "5", "9"].includes(c.scenario))
      c.executions = el.checked ? [el.value] : [];
    else
      c.executions = el.checked
        ? [...new Set([...c.executions, el.value])]
        : c.executions.filter((x) => x !== el.value);
    c.systems = p.systems
      .filter((s) => c.executions.includes(s.executionId))
      .map((s) => s.id);
  } else if (k === "system") {
    c.systems = el.checked
      ? [...new Set([...c.systems, el.value])]
      : c.systems.filter((x) => x !== el.value);
    if (c.scenario === "4" && el.checked) c.systems = [el.value];
  } else if (k === "attachment") {
    if (!c.attachments)
      c.attachments = assemblyActPlan(p, c.act, c.sections)
        .volumes.flatMap((v) => v.documents)
        .map((d) => d.id);
    c.attachments = el.checked
      ? [...new Set([...c.attachments, el.value])]
      : c.attachments.filter((x) => x !== el.value);
  } else if (k === "section")
    c.sections = el.checked
      ? [...new Set([...c.sections, el.value])]
      : c.sections.filter((x) => x !== el.value);
  else c[k] = el.value;
  if (["act", "execution"].includes(k)) delete c.attachments;
  const selected = assemblySelection(p, c);
  if (
    !p.systems.some(
      (s) =>
        selected.es.includes(s.executionId) &&
        s.acts.some((a) => a.id === c.act),
    )
  )
    c.act =
      p.systems
        .filter((s) => selected.es.includes(s.executionId))
        .flatMap((s) => s.acts)[0]?.id || "";
  save();
  render();
});
