A.assemblyRun = async (d) => {
  if (pdfExportBusy) return;
  const p = proj(d.p),
    c = assemblyPick(p);
  if (p.exportMode === "profile" && !exportProfile(p)) {
    toast("Выберите профиль заказчика");
    return;
  }
  pdfExportBusy = true;
  modal(
    "Подготовка экспорта",
    "<p>Проверка исходников, подстановка данных и расчёт фактических страниц…</p>",
    [],
  );
  try {
    await desktopFlush();
    let op, params;
    const prefix = slug(p.name);
    if (c.scenario === "11") {
      const { es, systems } = assemblySelection(p, c);
      if (!es.length) throw Error("Выберите выполнение");
      const state = structuredClone(S);
      state.projects = [assemblySubset(p, es, systems)];
      op = "exportPortable";
      params = { state, filename: prefix + "_Переносимый_комплект.zip" };
    } else {
      const plans = assemblyPlans(p, c);
      if (["7", "8"].includes(c.scenario)) {
        op = "exportPdfZip";
        params = { plans, filename: prefix + "_Отдельные_PDF.zip" };
      } else if (c.scenario === "12") {
        op = "exportRegistry";
        params = {
          plan: plans[0].plan,
          format: c.format,
          filename: prefix + "_Реестр." + c.format,
        };
      } else {
        op = "exportPdf";
        params = { plan: plans[0].plan, filename: prefix + "_Комплект.pdf" };
      }
    }
    if (
      ["exportPdf", "exportPdfZip", "exportRegistry"].includes(op) &&
      !(await confirmFrameWarnings(
        params.plans?.map((x) => x.plan) || [params.plan],
      ))
    )
      return null;
    const r = await desktopTrack(nativeCall(op, params));
    if (!r) {
      closeModal();
      return null;
    }
    modal(
      "Экспорт сохранён",
      `<p>${esc(r.path)}</p><p>${r.pages ? r.pages + " страниц" : ""}${r.files ? " · " + r.files + " файлов" : ""}</p>`,
      [{ l: "Готово", c: "pri" }],
    );
    return r;
  } catch (e) {
    modal(
      "Экспорт не выполнен",
      '<div style="white-space:pre-wrap">' +
        esc(e.message) +
        "</div>" +
        exportIssueLinks(e.details),
      [{ l: "Закрыть" }],
      "wide",
    );
    return null;
  } finally {
    pdfExportBusy = false;
  }
};
