function passportReview() {
  if (!S.meta.passportReviewPending) return "";
  return `<div class="card"><h3>Принадлежность прежних паспортов</h3><p>Выберите, какие паспорта оставить общими, а какие закрепить за объектом. Файлы будут перенесены после сохранения изменений.</p>${S.lib.base.map((b) => `<div class="row mb"><span class="grow">${esc(b.name)}</span><select data-passport-review="${b.id}"><option value="">Оставить общим</option>${S.projects.map((p) => `<option value="${p.id}">${esc(p.name)}</option>`).join("")}</select></div>`).join("")}${B("Применить распределение", "passportReview", "", "pri")}</div>`;
}
const manualBaseView = libBase;
libBase = (sel) => manualBaseView(sel) + passportReview();
A.passportReview = () => {
  if (!guard()) return;
  const choices = [...document.querySelectorAll("[data-passport-review]")]
    .filter((el) => el.value)
    .map((el) => ({ bid: el.dataset.passportReview, pid: el.value }));
  for (const { bid, pid } of choices) {
    const pending = S.trash.some((t) =>
      JSON.stringify(t.item).includes('"baseId":"' + bid + '"'),
    );
    if (pending) {
      toast(
        "Паспорт связан с карточками в корзине. Сначала восстановите или удалите эти связи.",
      );
      return;
    }
    if (proj(pid).materials.filter((m) => m.baseId === bid).length > 1) {
      toast("Сначала устраните повторные ссылки на материал в объекте.");
      return;
    }
    const others = S.projects.filter(
      (p) => p.id !== pid && p.materials.some((m) => m.baseId === bid),
    );
    if (others.length) {
      toast(
        "«" +
          S.lib.base.find((b) => b.id === bid).name +
          "» используется другими объектами. Он должен остаться общим.",
      );
      return;
    }
  }
  for (const { bid, pid } of choices) {
    const b = S.lib.base.find((b) => b.id === bid),
      p = proj(pid),
      linked = p.materials.filter((m) => m.baseId === bid);
    if (linked.length > 1) {
      toast(
        "Сначала устраните повторные ссылки на «" + b.name + "» в объекте.",
      );
      return;
    }
    let m = linked[0];
    if (!m) {
      m = { id: "m" + uid() };
      p.materials.push(m);
    }
    Object.assign(m, {
      name: b.name,
      category: b.category,
      brand: b.brand,
      maker: b.maker,
      note: b.note || "",
      baseId: "",
      scope: "object",
      docs: structuredClone(b.docs),
    });
    S.lib.base = S.lib.base.filter((x) => x.id !== bid);
  }
  S.meta.passportReviewPending = false;
  commit("Распределена принадлежность паспортов");
};
// Provide the same explicit save command on working pages, without changing their navigation.
const manualRender = render;
render = () => {
  ensureDesktopUi();
  manualRender();
  const page = $("#content .page");
  if (
    page &&
    page.querySelector('[data-f]:not([data-ent="ui"])') &&
    !page.querySelector('[data-a="desktopSave"]')
  ) {
    const header = page.querySelector(".ph .acts") || page.querySelector(".ph");
    if (header)
      header.insertAdjacentHTML(
        "beforeend",
        B("Сохранить изменения", "desktopSave", "", "pri"),
      );
  }
  const walker = document.createTreeWalker($("#content"), NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const n = walker.currentNode;
    n.nodeValue = n.nodeValue
      .replaceAll("Как в комплекта", "Как в комплекте")
      .replaceAll("как в комплекта", "как в комплекте");
  }
};

