const manualMaterialDocs = mDocs;
mDocs = (m) => {
  const docs = manualMaterialDocs(m);
  if (!m || m.baseId) return docs;
  return [
    ...docs,
    ...S.trash
      .filter(
        (t) =>
          t.ent === "row" &&
          t.ctx?.parentEnt === "mat" &&
          t.ctx.parentId === m.id &&
          t.ctx.path === "docs",
      )
      .map((t) => t.item),
  ];
};
const manualProjectMaterial = pMat;
pMat = (p, id) =>
  manualProjectMaterial(p, id) ||
  S.trash.find(
    (t) => t.ent === "mat" && t.ctx?.pid === p.id && t.item.id === id,
  )?.item;
const manualSources = pdfSources;
pdfSources = (p, v) => {
  const referenced = new Set(
    p.systems.flatMap((s) => [
      ...s.acts.flatMap((a) => a.materials),
      ...s.aik.map((k) => k.materialId),
    ]),
  );
  const archived = S.trash
    .filter(
      (t) =>
        t.ent === "mat" &&
        t.ctx?.pid === p.id &&
        referenced.has(t.item.id) &&
        !p.materials.some((m) => m.id === t.item.id),
    )
    .map((t) => t.item);
  return manualSources(
    archived.length ? { ...p, materials: [...p.materials, ...archived] } : p,
    v,
  );
};

