/* Document workflow: shared certificates, explicit company context and predictable editors. */
function shortFio(value) {
  const parts = String(value || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  return parts.length
    ? parts[0] +
        (parts.length > 1
          ? " " +
            parts
              .slice(1)
              .map((p) =>
                p
                  .split("-")
                  .map((n) => Array.from(n)[0] + ".")
                  .join("-"),
              )
              .join(" ")
          : "")
    : "";
}
