// Drag handles, with keyboard reordering for accessibility.
let exportDrag = null;

function installExportDrag() {
  for (const action of [
    "profileMove",
    "assemblyMove",
    "assemblyDocMove",
    "blkMv",
    "docMv",
  ])
    document
      .querySelectorAll('#content [data-a="' + action + '"]')
      .forEach((button) => {
        const row = button.closest(".row");
        if (!row) return;
        if (row.dataset.sortAction) {
          button.remove();
          return;
        }
        const d = {
          ...button.dataset,
        };
        row.dataset.sortAction = action;
        row.dataset.sortData = JSON.stringify(d);
        const locked =
          action !== "profileMove" && proj(d.p)?.exportMode === "profile";
        row.draggable = !locked;
        row.classList.add("export-sort-row");
        const handle = document.createElement("button");
        handle.type = "button";
        handle.className = "btn sm drag-handle";
        handle.textContent = "⠿";
        handle.disabled = locked;
        handle.title = "Перетащите; Alt + стрелка вверх/вниз";
        handle.setAttribute("aria-label", "Изменить порядок");
        row.prepend(handle);
        button.remove();
      });
}

function exportSortGroup(row) {
  const d = JSON.parse(row.dataset.sortData);
  return [
    row.dataset.sortAction,
    d.p || "",
    d.v || "",
    row.dataset.sortAction === "profileMove"
      ? d.id
      : row.dataset.sortAction === "assemblyDocMove"
        ? d.k
        : "",
  ].join("|");
}

function reorderExport(from, to) {
  if (
    !guard() ||
    !from ||
    !to ||
    from === to ||
    exportSortGroup(from) !== exportSortGroup(to)
  )
    return;
  const a = JSON.parse(from.dataset.sortData),
    b = JSON.parse(to.dataset.sortData),
    action = from.dataset.sortAction;
  let list, source, target;
  if (action === "profileMove") {
    list = prof(a.id).exportSettings.order;
    source = a.key;
    target = b.key;
  } else if (["assemblyMove", "assemblyDocMove"].includes(action)) {
    const p = proj(a.p);
    if (p.exportMode === "profile") return;
    const v = volumeList(p).find((v) => v.key === a.v),
      cfg = (S.volCfg[a.p + "|" + a.v] = S.volCfg[a.p + "|" + a.v] || {});
    if (action === "assemblyMove") {
      list = cfg.order = cfg.order || blocksFor(p, v).map((x) => x.key);
      source = a.k;
      target = b.k;
    } else {
      cfg.docs = cfg.docs || {};
      list = cfg.docs[a.k] =
        cfg.docs[a.k] ||
        blocksFor(p, v)
          .find((x) => x.key === a.k)
          .items.map((x) => x.id);
      source = a.id;
      target = b.id;
    }
  } else return;
  const i = list.indexOf(source),
    j = list.indexOf(target);
  if (i < 0 || j < 0) return;
  list.splice(i, 1);
  list.splice(j, 0, source);
  commit("Изменён порядок экспорта");
}
document.addEventListener("dragstart", (e) => {
  const row = e.target.closest(".export-sort-row");
  if (!row || !row.draggable) return;
  exportDrag = row;
  e.dataTransfer.effectAllowed = "move";
  e.dataTransfer.setData("text/plain", row.dataset.sortData);
  row.classList.add("dragging");
});
document.addEventListener("dragover", (e) => {
  const row = e.target.closest(".export-sort-row");
  if (
    exportDrag &&
    row &&
    exportSortGroup(exportDrag) === exportSortGroup(row)
  ) {
    e.preventDefault();
    document
      .querySelectorAll(".drop-target")
      .forEach((x) => x.classList.remove("drop-target"));
    row.classList.add("drop-target");
  }
});
document.addEventListener("drop", (e) => {
  const row = e.target.closest(".export-sort-row");
  if (exportDrag && row) {
    e.preventDefault();
    reorderExport(exportDrag, row);
  }
  exportDrag = null;
});
document.addEventListener("dragend", () => {
  exportDrag = null;
  document
    .querySelectorAll(".dragging,.drop-target")
    .forEach((x) => x.classList.remove("dragging", "drop-target"));
});
document.addEventListener("keydown", (e) => {
  if (
    !e.altKey ||
    !["ArrowUp", "ArrowDown"].includes(e.key) ||
    !e.target.matches(".drag-handle")
  )
    return;
  e.preventDefault();
  const row = e.target.closest(".export-sort-row"),
    rows = [...document.querySelectorAll(".export-sort-row")].filter(
      (x) => exportSortGroup(x) === exportSortGroup(row),
    ),
    i = rows.indexOf(row);
  reorderExport(row, rows[i + (e.key === "ArrowUp" ? -1 : 1)]);
});

