// Retry only after the user accepts concrete registers. No automatic truncation or font changes.
const printNativeCall = nativeCall;
let overflowDismiss = null;
const printCloseModal = closeModal;
closeModal = () => {
  const dismiss = overflowDismiss;
  overflowDismiss = null;
  if (dismiss) dismiss(false);
  printCloseModal();
};
nativeCall = async (op, params = {}) => {
  for (;;) {
    try {
      return await printNativeCall(op, params);
    } catch (error) {
      if (
        ![
          "exportPdf",
          "exportPdfZip",
          "exportRegistry",
          "exportPrintFolder",
          "exportSnapshot",
        ].includes(op)
      )
        throw error;
      const issues = (error.details || []).filter(
        (x) => x.kind === "actOverflow",
      );
      if (!issues.length) throw error;
      const candidates = issues.filter((x) => x.actId && x.suggested?.length);
      if (!candidates.length) throw error;
      const accepted = await new Promise((resolve) => {
        overflowDismiss = resolve;
        modal(
          "АОСР не помещается в две страницы",
          `<p>Предлагаемые реестры сохранят полные перечни, а в акте останутся ссылки. После этого число страниц будет проверено повторно.</p>${issues.map((x) => `<p><b>${esc(x.number)}</b> — ${x.pages} стр.${x.suggested.length ? "<br>Вынести в реестры: " + x.suggested.map((k) => esc(ACT_REGISTERS.find((r) => r[0] === k)[1])).join(", ") : "<br>Все доступные реестры уже включены; требуется исправить текст или шаблон."}</p>`).join("")}`,
          [
            { l: "Вернуться к карточкам", f: () => resolve(false) },
            { l: "Применить и пересобрать", c: "pri", f: () => resolve(true) },
          ],
          "wide",
        );
      });
      if (!accepted) return null;
      if (!guard()) return null;
      for (const issue of candidates) {
        const a = getEnt("act", issue.actId);
        if (!a) throw Error("Акт удалён");
        a.registers = a.registers || {};
        for (const k of issue.suggested)
          a.registers[k] = { ...a.registers[k], enabled: true };
      }
      commit("Вынесены перечни АОСР в реестры");
      await desktopFlush();
      for (const plan of params.plans?.map((x) => x.plan) || [params.plan])
        for (const v of plan.volumes)
          for (const doc of v.documents) {
            if (!doc.actRegister) continue;
            const a = getEnt("act", doc.actRegister.actId);
            doc.actRegister.settings = structuredClone(a.registers || {});
            for (const reg of Object.values(doc.actRegister.settings))
              if (reg.date) reg.date = fmtD(reg.date);
          }
      modal(
        "Повторная сборка",
        "<p>Формирование реестров и проверка двух страниц АОСР…</p>",
        [],
      );
    }
  }
};

